    self.refresh:SetText(LFG_LIST_SEARCH_AGAIN .. (not busy and cooldown > 0 and (" (" .. cooldown .. ")") or ""))
    self.spinner:SetShown(busy == true)
    if busy then
        if not self.spinner.animation:IsPlaying() then self.spinner.animation:Play() end
