        self.searchRefreshTimer = C_Timer.NewTimer(1, --[[APR_DIAG]]APRTrace("APR-Core/ui/panels/PartyFinderPanel.lua:336:callback#27", --[[/APR_DIAG]]function()
            self.searchRefreshTimer = nil
